// config.js — single source of truth for configuration
// Run: require('dotenv').config() before importing this

const config = {
    env:  process.env.NODE_ENV || 'development',
    port: parseInt(process.env.PORT || '3000', 10),

    db: {
        url: process.env.DB_URL,
    },

    auth: {
        jwtSecret: process.env.JWT_SECRET,
        jwtExpiresIn: '7d',
    },

    cors: {
        origins: (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean),
    },

    log: {
        level: process.env.LOG_LEVEL || 'info',
    },
};

// Validate required variables in production
if (config.env === 'production') {
    const required = ['DB_URL', 'JWT_SECRET'];
    for (const key of required) {
        if (!process.env[key]) throw new Error(`Missing required env var: ${key}`);
    }
    if (config.auth.jwtSecret === 'super-secret-dev-key-change-in-production') {
        throw new Error('Change JWT_SECRET before deploying!');
    }
}

module.exports = config;

